import pandas as pd
import numpy as np
from collections import Counter
from itertools import permutations

# Read the Data sheet
df = pd.read_excel('/root/data.xlsx', sheet_name='Data', header=None)

# Find the header row
for i in range(len(df)):
    if 'Turn number' in str(df.iloc[i].values):
        header_row = i
        break

# Re-read with correct header
df = pd.read_excel('/root/data.xlsx', sheet_name='Data', header=header_row)
df = df.dropna(subset=['Turn number'])
df = df[['Turn number', 'Game number', 'Roll 1', 'Roll 2', 'Roll 3', 'Roll 4', 'Roll 5', 'Roll 6']]
df = df.astype(int)

# Scoring functions
def high_and_often(rolls):
    counts = Counter(rolls)
    max_val = max(rolls)
    return max_val * counts[max_val]

def summation(rolls):
    return sum(rolls)

def highs_and_lows(rolls):
    h = max(rolls)
    l = min(rolls)
    return h * l * (h - l)

def only_two_numbers(rolls):
    if len(set(rolls)) == 2:
        return 30
    return 0

def all_the_numbers(rolls):
    if set(rolls) == {1, 2, 3, 4, 5, 6}:
        return 40
    return 0

def ordered_subset_of_four(rolls):
    for i in range(len(rolls) - 3):
        seq = [int(x) for x in rolls[i:i+4]]
        if seq[1] == seq[0] + 1 and seq[2] == seq[1] + 1 and seq[3] == seq[2] + 1:
            return 50
        if seq[1] == seq[0] - 1 and seq[2] == seq[1] - 1 and seq[3] == seq[2] - 1:
            return 50
    return 0

# Calculate all scores for a turn
def get_all_scores(rolls):
    return {
        'high_and_often': high_and_often(rolls),
        'summation': summation(rolls),
        'highs_and_lows': highs_and_lows(rolls),
        'only_two_numbers': only_two_numbers(rolls),
        'all_the_numbers': all_the_numbers(rolls),
        'ordered_subset_of_four': ordered_subset_of_four(rolls)
    }

# Find the best combined score for a game (2 turns, each category used at most once)
def best_game_score(scores1, scores2):
    """Find the maximum combined score when each category can be used only once total"""
    categories = list(scores1.keys())
    best_score = 0

    # Try all combinations: assign category i to turn 1, category j to turn 2 (i != j)
    for cat1 in categories:
        for cat2 in categories:
            if cat1 != cat2:
                score = scores1[cat1] + scores2[cat2]
                if score > best_score:
                    best_score = score

    return best_score

# Build a dictionary mapping game number to its turns
game_turns = {}
for _, row in df.iterrows():
    game_num = int(row['Game number'])
    rolls = [int(row[f'Roll {i}']) for i in range(1, 7)]
    if game_num not in game_turns:
        game_turns[game_num] = []
    game_turns[game_num].append(rolls)

# Calculate game scores
game_scores = {}
for game_num, turns in game_turns.items():
    if len(turns) == 2:
        scores1 = get_all_scores(turns[0])
        scores2 = get_all_scores(turns[1])
        game_scores[game_num] = best_game_score(scores1, scores2)
    else:
        # Handle games with only 1 turn (shouldn't happen normally)
        scores = get_all_scores(turns[0])
        game_scores[game_num] = max(scores.values())

# Show some sample game scores
print("Sample game scores:")
for i in range(1, 11):
    print(f"Game {i}: {game_scores[i]}")

# Now match games: odd vs even (game 1 vs 2, game 3 vs 4, etc.)
# Player 1 plays odd games, Player 2 plays even games
player1_wins = 0
player2_wins = 0
ties = 0

for i in range(1, 3000, 2):  # 1, 3, 5, ..., 2999
    odd_game = i  # Player 1
    even_game = i + 1  # Player 2

    if odd_game in game_scores and even_game in game_scores:
        p1_score = game_scores[odd_game]
        p2_score = game_scores[even_game]

        if p1_score > p2_score:
            player1_wins += 1
        elif p2_score > p1_score:
            player2_wins += 1
        else:
            ties += 1

print(f"\nPlayer 1 wins: {player1_wins}")
print(f"Player 2 wins: {player2_wins}")
print(f"Ties: {ties}")
print(f"\nAnswer (P1 wins - P2 wins): {player1_wins - player2_wins}")
